#' lrmodel_summary
#'
#' Summarizes results from a linear regression model
#' @param model a linear regression model object generated by lrmodel
#' @return a formatted summary of the linear regression model results, including:
#'
#' - Model call
#' - Distribution of residuals
#' - Table of coefficients, standard errors, t statistics, and p-values
#' - Residual standard error
#' - Multiple R-squared and adjusted R-squared
#' - F-statistic
#'
#' @examples
#' model1 <- lrmodel(mpg ~ wt, data = mtcars)
#' lrmodel_summary(model1)
#' @export

lrmodel_summary <- function(model) {
  # Model call
  call <- model$call

  # Model residuals
  residuals <- model$residuals
  res_summary <- summary(residuals)[-4]

  # Model coefficients
  est <- model$coefficients

  # Coefficient standard errors
  covariates <- paste(colnames(model$model[-1]), collapse = " + ")
  x <- model.matrix(as.formula(paste("~", covariates)), data = model$model)
  n_param <- model$rank
  rss <- sum((model$model[, 1] - model$fitted.values)^2)
  n <- nrow(model$model)
  res_var <- rss/(n - n_param)
  se <- sqrt(res_var*diag(solve(t(x)%*%x)))

  # t value
  t <- est/se

  # p value
  p <- pt(abs(t), df = model$df.residual, lower.tail = F)*2

  # Significance codes
  sig.codes <- rep(NA, n_param)
  sig.codes[p > 0.1 & p <= 1] = " "
  sig.codes[p > 0.05 & p <= 0.1] = "."
  sig.codes[p > 0.01 & p <= 0.05] = "*"
  sig.codes[p > 0.001 & p <= 0.01] = "**"
  sig.codes[p <= 0.001] = "***"

  # Table of coefficients
  coefficients <- cbind(
    "Estimate" = est,
    "Std. Error" = se,
    "t value" = t,
    "Pr(>|t|)" = p
  )

  # Residual se (sigma) and df
  sigma <- sqrt(res_var)
  res_df <- model$df.residual

  # R-squared
  sse <- sum((residuals)^2)
  y <- model$model[, 1]
  sst <- sum((y - mean(y))^2)
  r.squared <- 1 - (sse/sst)
  adj.r.squared <- 1 - (1 - r.squared)*((n - 1)/(n - n_param))

  # F-statistic
  ssr <- sum((model$fitted.values - mean(y))^2)
  f <- (ssr/(n_param - 1))/(sse/(n - n_param))
  f_df1 <- n_param - 1
  p_f <- pf(f, f_df1, res_df, lower.tail = F)

  # Store results in a list
  summary_results <- list(
    call = call,
    residuals = residuals,
    coefficients = coefficients,
    sigma = sigma,
    r.squared = r.squared,
    adj.r.squared = adj.r.squared,
    fstatistic = c("value" = f, "numdf" = f_df1, "dendf" = res_df),
    n_obs_del = model$n_obs_del,
    sig.codes = sig.codes
  )

  class(summary_results) <- "lrmodel_summary"

  return(summary_results)
}


#' print.lrmodel_summary
#'
#' The print method for the lrmodel_summary function. Prints a formatted summary
#' of the linear model results.
#'
#' @param x a list object generated by lrmodel_summary
#' @param ... additional arguments
#'
#' @export

# Print method for lrmodel_summary()
print.lrmodel_summary <- function(x, ...) {
  # Formatted summary
  cat("Call:\n")
  print(x$call)
  cat("\nResiduals:\n")
  print(summary(x$residuals)[-4])
  cat("\nCoefficients:\n")
  print(data.frame(x$coefficients, " " = x$sig.codes, check.names = F))
  cat("---\nSignif. codes: 0 '***', 0.001 '**' 0.01 '*' 0.05 '.' 0.1 ' ' 1\n")
  cat("\nResidual standard error:", x$sigma, "on", x$fstatistic["dendf"], "degrees of freedom\n")
  if (x$n_obs_del != 0) {cat("(", x$n_obs_del, " observations deleted due to missingness)\n", sep = "")}
  cat("Multiple R-squared:", x$r.squared,", Adjusted R-squared:", x$adj.r.squared, "\n")
  cat("F-statistic:", x$fstatistic[1], "on", x$fstatistic[2], "and", x$fstatistic[3], "DF,", "p-value:", pf(x$fstatistic[1], x$fstatistic[2], x$fstatistic[3], lower.tail = F))
  invisible(x)
}
